        super.tick();
        prevFlyProgress = flyProgress;
        prevFlightPitch = flightPitch;
        prevFlightRoll = flightRoll;
        prevFlapAmount = flapAmount;
        if (isFlying() && flyProgress < 5F) {
            flyProgress++;
        }
        if (!isFlying() && flyProgress > 0F) {
            flyProgress--;
        }
        float yMov = (float) this.getDeltaMovement().y;
        float xzMov = (float) this.getDeltaMovement().horizontalDistance();
        if (xzMov > 0) {
            if (flapAmount < 5F) {
                flapAmount += 1F;
            }
        } else if (xzMov <= 0.05F) {
            if (flapAmount > 0) {
                flapAmount -= 0.5F;
            }
        }
        if (isFlying()) {
            if (this.isLandNavigator) {
                switchNavigator(false);
            }
            if(flapAmount > 0 && isAlive() && flapTime-- <= 0){
                flapTime = 8 + random.nextInt(10);
                this.playSound(ACSoundRegistry.GLOOMOTH_FLAP.get(), 0.7F, 1.0F);
