    }

    private boolean isWithinMothBallRange(BlockPos blockPos, int range) {
        BlockState state = level().getBlockState(blockPos);
        if (state.is(ACBlockRegistry.MOTH_BALL.get())) {
            float balls = state.getValue(MothBallBlock.BALLS) / 5F;
            int distance = (int) Math.sqrt(blockPos.distSqr(this.blockPosition()));
            return distance < balls * range;
        }
        return false;
    }

    @Override
    public void triggerSacrificeIn(int time) {
        isBeingSacrificed = true;
        sacrificeTime = time;
    }

    @Override
    public boolean isValidSacrifice(int distanceFromGround) {
        return distanceFromGround < 4;
    }

    private void doInitialPosing(LevelAccessor world) {
        BlockPos above = this.blockPosition();
        int upBy = 3 + random.nextInt(5);
        int k = 0;
        while (world.isEmptyBlock(above) && above.getY() < level().getMaxBuildHeight() && k < upBy) {
            above = above.above();
            k++;
        }
        this.setFlying(true);
        this.setPos(above.getX() + 0.5F, above.getY(), above.getZ() + 0.5F);
    }

    @javax.annotation.Nullable
    public SpawnGroupData finalizeSpawn(ServerLevelAccessor worldIn, DifficultyInstance difficultyIn, MobSpawnType reason, @javax.annotation.Nullable SpawnGroupData spawnDataIn, @javax.annotation.Nullable CompoundTag dataTag) {
        if (reason == MobSpawnType.NATURAL) {
            doInitialPosing(worldIn);
        }
        return super.finalizeSpawn(worldIn, difficultyIn, reason, spawnDataIn, dataTag);
    }


    protected SoundEvent getHurtSound(DamageSource damageSource) {
        return ACSoundRegistry.GLOOMOTH_HURT.get();
    }

    protected SoundEvent getDeathSound() {
        return ACSoundRegistry.GLOOMOTH_DEATH.get();
    }

    class FlightMoveHelper extends MoveControl {

        public FlightMoveHelper(GloomothEntity gloomoth) {
            super(gloomoth);
        }

        public void tick() {
            int maxRotChange = 10;
            boolean flag = false;
            if (this.operation == Operation.MOVE_TO && !this.mob.getNavigation().isDone()) {
                //Vec3 ed = this.mob.getNavigation().getTargetPos().getCenter();
                //((ServerLevel)mob.level).sendParticles(ParticleTypes.HEART, ed.x, ed.y, ed.z, 0, 0, 0, 0, 1);
                //((ServerLevel)mob.level).sendParticles(ParticleTypes.SNEEZE, wantedX, wantedY, wantedZ, 0, 0, 0, 0, 1);
                double d0 = this.wantedX - this.mob.getX();
                double d1 = this.wantedY - this.mob.getY();
                double d2 = this.wantedZ - this.mob.getZ();
                double d3 = Mth.sqrt((float) (d0 * d0 + d1 * d1 + d2 * d2));
                double d4 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                d1 /= d3;
                this.mob.yBodyRot = this.mob.getYRot();
                float f1 = (float) (this.speedModifier * this.mob.getAttributeValue(Attributes.MOVEMENT_SPEED) * 3);
                float rotBy = maxRotChange;
                this.mob.setDeltaMovement(this.mob.getDeltaMovement().add(0.0D, (double) f1 * d1 * 0.025D, 0.0D));
                if (d4 < this.mob.getBbWidth() + 1.4F) {
                    f1 *= 0.7F;
                    if (d4 < 0.3F) {
                        rotBy = 0;
                    } else {
                        rotBy = Math.max(40, maxRotChange);
                    }
                } else {
                    flag = true;
                }
                float f = (float) (Mth.atan2(d2, d0) * 57.2957763671875D) - 90.0F;
                this.mob.setYRot(this.rotlerp(this.mob.getYRot(), f, rotBy));
                if (d3 > 0.3) {
                    this.mob.setSpeed(f1);
                    flag = true;
                } else {
                    this.mob.setSpeed(0.0F);
                }
            } else {
                this.mob.setSpeed(0.0F);
            }
            this.mob.setNoGravity(flag);
        }
    }


}

package com.github.alexmodguy.alexscaves.server.entity.ai;

import com.github.alexmodguy.alexscaves.server.entity.living.UnderzealotEntity;
import com.github.alexmodguy.alexscaves.server.entity.living.VesperEntity;
import com.github.alexmodguy.alexscaves.server.entity.util.UnderzealotSacrifice;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import java.util.EnumSet;
import java.util.List;

public class UnderzealotCaptureSacrificeGoal extends Goal {
    private UnderzealotEntity entity;
    private LivingEntity sacrifice;

    private int validTimeCheck = 0;

    public UnderzealotCaptureSacrificeGoal(UnderzealotEntity underzealot) {
        this.entity = underzealot;
        this.setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
    }

    @Override
    public boolean canUse() {
        LivingEntity target = entity.getTarget();
        long worldTime = entity.level().getGameTime() % 10;
        if (entity.isCarrying() || entity.isPackFollower() || entity.sacrificeCooldown > 0) {
            return false;
        }
        if ((worldTime != 0 || entity.getRandom().nextInt(3) != 0) && (target == null || !target.isAlive())) {
            return false;
        }
        AABB aabb = entity.getBoundingBox().inflate(20);
        List<LivingEntity> list = entity.level().getEntitiesOfClass(LivingEntity.class, aabb, this::isFirstValidSacrifice);
        if (!list.isEmpty()) {
            LivingEntity closest = null;
            for (LivingEntity mob : list) {
                if ((closest == null || mob.distanceToSqr(entity) < closest.distanceToSqr(entity)) && entity.hasLineOfSight(mob)) {
                    closest = mob;
                }
            }
            sacrifice = closest;
            return sacrifice != null;
        }
        return false;
    }

    private boolean isFirstValidSacrifice(LivingEntity entity) {
        return isValidSacrifice(entity) && (entity instanceof VesperEntity || entity.getRandom().nextInt(4) == 0);
    }

    private boolean isValidSacrifice(LivingEntity entity) {
        return entity instanceof UnderzealotSacrifice sacrifice && !entity.isPassenger() && sacrifice.isValidSacrifice(getDistanceToGround(entity));
    }

    private int getDistanceToGround(LivingEntity entity) {
        int downBy = 0;
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos(entity.getBlockX(), entity.getBlockY(), entity.getBlockZ());
        while (entity.level().isEmptyBlock(pos) && pos.getY() > entity.level().getMinBuildHeight()) {
            pos.move(0, -1, 0);
            downBy++;
        }
        return downBy;
    }

    @Override
    public boolean canContinueToUse() {
        return sacrifice != null && sacrifice.isAlive() && !sacrifice.isPassenger() && !entity.isPackFollower() && entity.distanceTo(sacrifice) < 32 && entity.sacrificeCooldown <= 0;
    }

    public void stop() {
        this.entity.getNavigation().stop();
    }

    public void start() {
        validTimeCheck = 0;
    }

    public void tick() {
        double distance = entity.distanceTo(sacrifice);
        entity.getNavigation().moveTo(sacrifice, 1.0F);
        if (distance < 1.4F) {
            sacrifice.startRiding(entity);
        }
        Vec3 sub = sacrifice.position().subtract(entity.position());
        if (!entity.isBuried() && sub.y > 0.5F && sub.horizontalDistance() < 2.0F && entity.onGround()) {
            entity.jumpFromGround();
        }
        validTimeCheck++;
        if (validTimeCheck % 100 == 0 && !isValidSacrifice(sacrifice)) {
            sacrifice = null;
        }
    }
}

package com.github.alexmodguy.alexscaves.server.entity.ai;

import com.github.alexmodguy.alexscaves.server.entity.living.UnderzealotEntity;
import com.github.alexmodguy.alexscaves.server.entity.util.PackAnimal;
import com.github.alexmodguy.alexscaves.server.entity.util.UnderzealotSacrifice;
import net.minecraft.commands.arguments.EntityAnchorArgument;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.level.pathfinder.Node;
import net.minecraft.world.level.pathfinder.Path;
import net.minecraft.world.phys.Vec3;

import java.util.EnumSet;

public class UnderzealotSacrificeGoal extends Goal {

    private final UnderzealotEntity entity;
    private int executionCooldown = 10;
    private int attemptToFollowTicks = 0;
    private BlockPos center;

    public UnderzealotSacrificeGoal(UnderzealotEntity entity) {
        this.setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
        this.entity = entity;
    }

    @Override
    public boolean canUse() {
        if (entity.sacrificeCooldown > 0) {
            return false;
        }
        if (entity.isPackFollower()) {
            UnderzealotEntity leader = (UnderzealotEntity) entity.getPackLeader();
            if (leader.isCarrying() && leader.getLastSacrificePos() != null && leader.distanceToSqr(Vec3.atCenterOf(leader.getLastSacrificePos())) < 2.5F) {
                center = leader.getLastSacrificePos();
                return true;
            }
        } else if (entity.isCarrying()) {
            if (executionCooldown-- > 0) {
                return false;
            } else {
                executionCooldown = 20 + entity.getRandom().nextInt(100);
                BlockPos pos = null;
                if (entity.getLastSacrificePos() != null) {
                    if (isValidSacrificePos(entity.getLastSacrificePos())) {
                        executionCooldown = 10;
                        pos = entity.getLastSacrificePos();
                    } else {
                        entity.setLastSacrificePos(null);
                    }
                }
                if (pos == null) {
                    pos = findNearestSacrificePos();
                }
                if (pos != null) {
                    center = pos;
                    entity.setLastSacrificePos(center);
                    return true;
                }
            }
        }
        return false;
    }

    private BlockPos findNearestSacrificePos() {
        BlockPos.MutableBlockPos check = new BlockPos.MutableBlockPos();
        check.move(entity.blockPosition());
        check.move(0, -1, 0);
        if (isValidSacrificePos(check)) {
            return check.immutable();
        }
        for (int i = 0; i < 20; i++) {
            check.move(entity.blockPosition());
            check.move(entity.getRandom().nextInt(20) - 10, 5, entity.getRandom().nextInt(20) - 10);
            if (!entity.level().isLoaded(check)) {
                continue;
            }
            while (entity.level().isEmptyBlock(check) && check.getY() > entity.level().getMinBuildHeight()) {
                check.move(0, -1, 0);
            }
            if (isValidSacrificePos(check) && canReach(check)) {
                return check.immutable();
            }
        }
        return null;
    }

    public boolean canReach(BlockPos target) {
        Path path = this.entity.getNavigation().createPath(target, 0);
        if (path == null) {
            return false;
        } else {
            Node node = path.getEndNode();
            if (node == null) {
                return false;
            } else {
                int i = node.x - target.getX();
                int j = node.y - target.getY();
                int k = node.z - target.getZ();
                return (double) (i * i + j * j + k * k) <= 3D;
            }
        }
    }

    private boolean isValidSacrificePos(BlockPos pos) {
        if (entity.level().isEmptyBlock(pos)) {
            return false;
        }
        BlockPos.MutableBlockPos aboveGround = new BlockPos.MutableBlockPos();
        BlockPos.MutableBlockPos below = new BlockPos.MutableBlockPos();
        int badSpots = 0;
        for (int i = -2; i <= -2; i++) {
            for (int j = -2; j <= -2; j++) {
                aboveGround.set(pos.getX() + i, pos.getY() + 1, pos.getZ() + j);
                below.set(pos.getX() + i, pos.getY(), pos.getZ() + j);
                if (entity.level().isEmptyBlock(below)) {
                    badSpots++;
                }
                if (badSpots > 5) {
                    return false;
                }
            }
        }
        return true;
    }

    @Override
    public boolean canContinueToUse() {
        if (center == null) {
            return false;
        }
        if (entity.sacrificeCooldown > 0) {
            return false;
        }
        if (entity.isPackFollower()) {
            UnderzealotEntity leader = (UnderzealotEntity) entity.getPackLeader();
            return leader != null && leader.isCarrying() && leader.distanceToSqr(Vec3.atCenterOf(center)) < 5F;
        } else {
            return entity.isCarrying();
        }
    }

    public void tick() {
        if (this.entity.isDiggingInProgress() || this.entity.isBuried()) {
            this.entity.setPraying(false);
            return;
        }
        if (center != null) {
            int worshippingTicks = this.entity.getWorshipTime();
            if (entity.isPackFollower()) {
                UnderzealotEntity leader = (UnderzealotEntity) entity.getPackLeader();
                float f = getPackPosition() / ((float) entity.getPackSize() - 1);
                Vec3 offset = new Vec3(2, 0, 0).yRot(f * ((float) Math.PI * 2F));
                Vec3 at = groundOf(Vec3.atCenterOf(center).add(offset));
                entity.getNavigation().moveTo(at.x, at.y, at.z, 1);
                if (entity.isPraying()) {
                    attemptToFollowTicks = 0;
                } else if ((entity.getNavigation().isStuck() || attemptToFollowTicks > 60) && this.entity.distanceToSqr(at) > 8) {
                    entity.setBuried(true);
                    entity.reemergeAt(BlockPos.containing(at).above(), 20 + entity.getRandom().nextInt(20));
                }
                if (leader != null && leader.sacrificeCooldown > 0) {
                    this.entity.sacrificeCooldown = leader.sacrificeCooldown;
                }
                if (leader != null && this.entity.distanceToSqr(at) < 4) {
                    entity.setPraying(true);
                    Vec3 slightOffset = at.subtract(entity.position());
                    if (slightOffset.length() > 1F) {
                        slightOffset = slightOffset.normalize();
                    }
                    this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(slightOffset.scale(0.04F)));
                    entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(center));
                    BlockPos pos = leader.getLastSacrificePos() == null ? leader.blockPosition().above(5) : leader.getLastSacrificePos().above(5);
                    this.entity.setParticlePos(pos);
                    entity.level().broadcastEntityEvent(entity, (byte) 77);
                    if (worshippingTicks % 10 == 0) {
                        this.entity.level().broadcastEntityEvent(entity, (byte) 61);
                    }
                    this.entity.setWorshipTime(worshippingTicks + 1);
                } else {
                    this.entity.setWorshipTime(0);
                    attemptToFollowTicks++;
                }
            } else {
                this.entity.setParticlePos(center.above(5));
                Vec3 at = Vec3.atCenterOf(center);
                if (this.entity.distanceToSqr(at) < 4) {
                    Vec3 slightOffset = at.subtract(entity.position());
                    if (slightOffset.length() > 1F) {
                        slightOffset = slightOffset.normalize();
                    }
                    this.entity.setWorshipTime(worshippingTicks + 1);
                    this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(slightOffset.scale(0.04F)));
                    if (worshippingTicks > UnderzealotEntity.MAX_WORSHIP_TIME - 300 && this.entity.cloudCooldown <= 0 && entity.isSurroundedByPrayers()) {
                        if (entity.getFirstPassenger() instanceof UnderzealotSacrifice underzealotSacrifice) {
                            underzealotSacrifice.triggerSacrificeIn(300);
                            entity.cloudCooldown = 400;
                            entity.level().broadcastEntityEvent(entity, (byte) 62);
                        }
                    }
                } else {
                    this.entity.setWorshipTime(0);
                }
                entity.getNavigation().moveTo(center.getX(), center.getY(), center.getZ(), 1);
            }
        }
    }

    private Vec3 groundOf(Vec3 in) {
        BlockPos origin = BlockPos.containing(in);
        BlockPos.MutableBlockPos blockPos = origin.mutable();
        while (!entity.level().isEmptyBlock(blockPos) && blockPos.getY() < entity.level().getMaxBuildHeight()) {
            blockPos.move(0, 1, 0);
        }
        while (entity.level().isEmptyBlock(blockPos.below()) && blockPos.getY() > entity.level().getMinBuildHeight()) {
            blockPos.move(0, -1, 0);
        }
        return new Vec3(in.x, blockPos.getY(), in.z);
    }

    private int getPackPosition() {
        PackAnimal leader = entity.getPackLeader();
        int i = 1;
        while (leader.getAfterPackMember() != null) {
            if (leader.getAfterPackMember() == entity) {
                return i;
            }
            leader = leader.getAfterPackMember();
            i++;
        }
        return i;
    }

    public void stop() {
        attemptToFollowTicks = 0;
        this.entity.setWorshipTime(0);
        if (this.entity.sacrificeCooldown == 0) {
            this.entity.sacrificeCooldown = 100;
        }
        this.entity.getNavigation().stop();
        this.entity.ejectPassengers();
        this.entity.setPraying(false);
        this.entity.setParticlePos(null);
    }
}

package com.github.alexmodguy.alexscaves.server.entity.ai;

import com.github.alexmodguy.alexscaves.server.entity.living.UnderzealotEntity;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.phys.Vec3;

import java.util.EnumSet;

public class UnderzealotProcessionGoal extends Goal {
    public final UnderzealotEntity entity;
    private double speedModifier;
    private int attemptToFollowTicks = 0;

    public UnderzealotProcessionGoal(UnderzealotEntity underzealot, double speed) {
        this.entity = underzealot;
        this.speedModifier = speed;
        this.setFlags(EnumSet.of(Goal.Flag.MOVE));
    }

    public boolean canUse() {
        if (this.entity.getRandom().nextInt(20) == 0 && this.entity.isPackFollower() && this.entity.getPriorPackMember() != null) {
            return true;
        } else {
            return false;
        }
    }

    public boolean canContinueToUse() {
        return this.entity.isPackFollower() && this.entity.getPriorPackMember() != null;
    }

    public void stop() {
        this.entity.getNavigation().stop();
        attemptToFollowTicks = 0;
    }

    public void tick() {
        if (this.entity.isDiggingInProgress() || this.entity.isBuried()) {
            this.entity.setPraying(false);
            return;
        }
        if (this.entity.getPriorPackMember() != null) {
            UnderzealotEntity priorPackMember = (UnderzealotEntity) this.entity.getPriorPackMember();
            double distanceTo = (double) this.entity.distanceTo(priorPackMember);
            if (distanceTo > this.entity.getBbWidth() + 0.5F) {
                Vec3 vec3;
                vec3 = (new Vec3(priorPackMember.getX() - this.entity.getX(), priorPackMember.getY() - this.entity.getY(), priorPackMember.getZ() - this.entity.getZ())).normalize().scale(Math.max(distanceTo - 1.0D, 0.0D));
                this.entity.getNavigation().moveTo(this.entity.getX() + vec3.x, this.entity.getY() + vec3.y, this.entity.getZ() + vec3.z, this.speedModifier);
            }
            if (distanceTo > 8) {
                attemptToFollowTicks++;
                if ((entity.getNavigation().isStuck() || attemptToFollowTicks > 60)) {
                    entity.setBuried(true);
                    entity.reemergeAt(priorPackMember.blockPosition(), 20 + entity.getRandom().nextInt(20));
                }
            } else {
                attemptToFollowTicks = 0;
            }
        }
    }

}

