public interface UnderzealotSacrifice {

    void triggerSacrificeIn(int time);

    boolean isValidSacrifice(int distanceFromGround);

}

package com.github.alexmodguy.alexscaves.server.entity.util;

import net.minecraft.world.entity.LivingEntity;

public interface PackAnimal {

    default boolean isPackFollower() {
        return this.getPriorPackMember() != null;
    }

    default boolean hasPackFollower() {
        return this.getAfterPackMember() != null;
    }

    default PackAnimal getPackLeader() {
        PackAnimal leader = this;
        while (leader.getPriorPackMember() != null && leader.getPriorPackMember() != this) {
            leader = leader.getPriorPackMember();
        }
        return leader;
    }

    default int getPackSize() {
        PackAnimal leader = getPackLeader();
        int i = 1;
        while (leader.getAfterPackMember() != null) {
            leader = leader.getAfterPackMember();
            i++;
        }
        return i;
    }

    default boolean isInPack(PackAnimal packAnimal) {
        PackAnimal leader = getPackLeader();
        while (leader.getAfterPackMember() != null) {
            if (packAnimal.equals(leader)) {
                return true;
            }
            leader = leader.getAfterPackMember();
        }
        return false;
    }

    default boolean isValidLeader(PackAnimal packLeader) {
        return !packLeader.isPackFollower() && ((LivingEntity) packLeader).isAlive();
    }

    PackAnimal getPriorPackMember();

    PackAnimal getAfterPackMember();

    void setPriorPackMember(PackAnimal animal);

    void setAfterPackMember(PackAnimal animal);

    default void joinPackOf(PackAnimal caravanHeadIn) {
        setPriorPackMember(caravanHeadIn);
        caravanHeadIn.setAfterPackMember(this);
        resetPackFlags();
    }

    default void leavePack() {
        if (this.getPriorPackMember() != null) {
            this.getPriorPackMember().setAfterPackMember(null);
        }
        this.setPriorPackMember(null);
        resetPackFlags();
    }

    default void resetPackFlags() {
    }
}

package com.github.alexmodguy.alexscaves.server.entity.ai;


import com.github.alexmodguy.alexscaves.server.entity.util.PackAnimal;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.goal.Goal;

import java.util.List;

public class AnimalJoinPackGoal extends Goal {
    public final LivingEntity entity;
    public final PackAnimal packAnimal;
    private int distCheckCounter;

    private int rate;
    private int packSize;

    public AnimalJoinPackGoal(LivingEntity animal, int rate, int packSize) {
        this.entity = animal;
        this.packAnimal = (PackAnimal) animal;
        this.rate = rate;
        this.packSize = packSize;
    }

    public boolean canUse() {
        long worldTime = entity.level().getGameTime() % 10;
        if (worldTime != 0 && entity.getRandom().nextInt(reducedTickDelay(rate)) != 0) {
            return false;
        }
        if (!this.packAnimal.isPackFollower() && !this.packAnimal.hasPackFollower()) {
            double dist = 30D;
            List<? extends LivingEntity> list = entity.level().getEntitiesOfClass(entity.getClass(), entity.getBoundingBox().inflate(dist, dist, dist));
            LivingEntity closestTail = null;
            double d0 = Double.MAX_VALUE;
            for (LivingEntity animal : list) {
                if (!((PackAnimal) animal).hasPackFollower() && ((PackAnimal) animal).isValidLeader(((PackAnimal) animal).getPackLeader()) && !animal.getUUID().equals(entity.getUUID()) && !((PackAnimal) animal).isInPack(packAnimal) && ((PackAnimal) animal).getPackSize() < packSize) {
                    double d1 = this.entity.distanceToSqr(animal);
                    if (!(d1 > d0)) {
                        d0 = d1;
                        closestTail = animal;
                    }
                }
            }
            if (closestTail == null) {
                return false;
            } else if (d0 < 1.0D) {
                return false;
            } else if (!packAnimal.isValidLeader(((PackAnimal) closestTail).getPackLeader())) {
                return false;
            } else {
                this.packAnimal.joinPackOf((PackAnimal) closestTail);
                return true;
            }
        } else {
            return false;
        }
    }

    public boolean canContinueToUse() {
        if (this.packAnimal.isPackFollower() && packAnimal.isValidLeader(packAnimal.getPackLeader())) {
            double d0 = this.entity.distanceToSqr((LivingEntity) this.packAnimal.getPriorPackMember());
            if (d0 > 676.0D) {
                if (this.distCheckCounter == 0) {
                    return false;
                }
            }
            if (this.distCheckCounter > 0) {
                --this.distCheckCounter;
            }

            return true;
        } else {
            return false;
        }
    }

    public void stop() {
        this.packAnimal.leavePack();
    }

    public void tick() {
    }
}

